import {SUBCONTRATOS} from './subcontratos.mjs';
import {weekDays,putAssignment,scheduleCapacity,teamKey,comparableHistory} from './lastplanner-daily.mjs';
import {sumarDias} from './lastplanner-model.mjs';
import {sessionActor} from './lastplanner-session.mjs';
export function dailyPlanner(form,initial,{activities=[],attendance=[]}={}){
 let rows=structuredClone(initial.schedule||[]),selected=form.elements.inicioPlan.value,visible=selected,editing=null;
 let rateAt=initial.estimateReference?.at||new Date().toISOString();
 let historical=initial.estimateReference?.status==='observado'?structuredClone(initial.estimateReference):null;
 const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const host=document.createElement('section');host.className='lpDaily';const step=form.querySelector('[data-step="2"]'),advanced=step.querySelector('details');advanced.querySelector('summary').textContent='Opciones avanzadas de rendimiento';step.insertBefore(host,advanced);form.elements.dotacion.closest('label').hidden=true;
 const rateLabel=form.elements.rendimientoPlan.closest('label');host.innerHTML='<h4>Personal programado</h4><div data-week-nav></div><div class="lpDays" data-days></div><div data-day-editor></div><h4>Rendimiento de referencia</h4><div data-simple-rate></div><p data-daily-capacity role="status"></p><p data-history></p><button type="button" data-use-history hidden>Usar referencia histórica observada</button><button type="button" data-trim hidden>Quitar asignaciones fuera del período</button><details><summary>Ver cálculo y antecedentes</summary><div data-calculation></div></details>';
 host.querySelector('[data-simple-rate]').append(rateLabel);const source=form.querySelector('[data-rate-source]');if(!initial.source||/^\d+$/.test(initial.source))source.value='Estimación provisional del supervisor';
 const references=activities.flatMap(a=>a.planificacion?.schedule||[]),teams=[...new Map([...references,...rows].map(r=>[r.teamId,r])).values()];
 const value=n=>form.elements[n].value;
 const reference=()=>{if(historical?.criteria&&(historical.criteria.partida!==form.querySelector('[data-part-name]').value.trim()||historical.criteria.unit!==value('unidad')||historical.criteria.contractor!==value('contratista')||JSON.stringify([...(historical.criteria.teams||[])].sort())!==JSON.stringify([...new Set(rows.map(r=>r.teamName))].sort())))historical=null;return ({...(historical||{}),rate:Number(value('rendimientoPlan')),unit:form.querySelector('[data-rate-unit]').value,basis:form.querySelector('[data-rate-basis]').value,crew:form.querySelector('[data-crew]').value.split('\n').filter(Boolean).map(v=>({role:v.split(':')[0],count:Number(v.split(':')[1])})),source:historical?.source||'Estimación provisional del supervisor',notes:form.querySelector('[data-rate-notes]').value,status:historical?'observado':'provisional',actor:sessionActor()?.id,at:rateAt});};
 const leave=()=>!host.querySelector('[data-apply-assignment]')||confirm('Hay un equipo sin aplicar. ¿Descartar únicamente esta edición?');
 const changed=()=>form.dispatchEvent(new Event('input',{bubbles:true}));
 function refresh(){if(!value('inicioPlan')||!value('finPlan'))return;if(visible<weekDays(value('inicioPlan'))[0]||visible>weekDays(value('finPlan'))[6])visible=value('inicioPlan');const days=weekDays(visible);if(!days.includes(selected))selected=days.find(d=>d>=value('inicioPlan')&&d<=value('finPlan'))||days[0];
 host.querySelector('[data-week-nav]').innerHTML=`<button type="button" data-prev ${days[0]<=weekDays(value('inicioPlan'))[0]?'disabled':''}>← Semana anterior</button><button type="button" data-next ${days[6]>=weekDays(value('finPlan'))[6]?'disabled':''}>Semana siguiente →</button>`;
 host.querySelector('[data-prev]').onclick=()=>{if(!leave())return;visible=sumarDias(days[0],-7);refresh();};host.querySelector('[data-next]').onclick=()=>{if(!leave())return;visible=sumarDias(days[0],7);refresh();};
 host.querySelector('[data-days]').innerHTML=days.map((date,i)=>`<button type="button" data-date="${date}" aria-pressed="${date===selected}" ${date<value('inicioPlan')||date>value('finPlan')?'disabled title="Fuera del período"':''}>${['LUN','MAR','MIÉ','JUE','VIE','SÁB','DOM'][i]}<b>${Number(date.slice(-2))}</b><small>${rows.filter(r=>r.date===date).reduce((n,r)=>n+r.people,0)} pers.</small></button>`).join('');host.querySelectorAll('[data-date]').forEach(b=>b.onclick=()=>{if(!leave())return;selected=b.dataset.date;editing=null;refresh();});renderDay();summarize();}
 function renderDay(){const el=host.querySelector('[data-day-editor]'),today=rows.filter(r=>r.date===selected);el.innerHTML=`<h4>${selected}</h4>${today.map(r=>`<p>${esc(r.contractor)} · ${esc(r.teamName)} · ${r.people} personas · ${r.fraction} jornada <button type="button" data-edit="${esc(r.id)}">Editar</button><button type="button" data-remove="${esc(r.id)}">Quitar</button></p>`).join('')||'<p>Sin personal programado.</p>'}<button type="button" data-add ${selected<value('inicioPlan')||selected>value('finPlan')?'disabled':''}>Agregar equipo</button><button type="button" data-copy>Copiar al día siguiente</button><details><summary>Repetir en varios días</summary>${weekDays(visible).filter(d=>d>=value('inicioPlan')&&d<=value('finPlan')&&d!==selected).map(d=>`<label class="check"><input type="checkbox" data-repeat-date="${d}">${d}</label>`).join('')}<button type="button" data-repeat>Aplicar a días marcados</button><button type="button" data-all>Aplicar a toda la semana</button></details><div data-assignment></div>`;
 el.querySelector('[data-add]').onclick=()=>edit(null);el.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>edit(rows.find(r=>r.id===b.dataset.edit)));el.querySelectorAll('[data-remove]').forEach(b=>b.onclick=()=>{if(!leave())return;rows=rows.filter(r=>r.id!==b.dataset.remove);refresh();changed();});
 const copy=dates=>{if(!leave())return;const valid=dates.filter(d=>d>=value('inicioPlan')&&d<=value('finPlan')&&d!==selected);if(valid.some(d=>rows.some(r=>r.date===d))&&!confirm('Se actualizarán los mismos equipos en los días de destino. Los otros equipos se conservan. ¿Continuar?'))return;for(const date of valid)for(const r of today)rows=putAssignment(rows,{...r,date});refresh();changed();};el.querySelector('[data-copy]').onclick=()=>copy([sumarDias(selected,1)]);el.querySelector('[data-repeat]').onclick=()=>copy([...el.querySelectorAll('[data-repeat-date]:checked')].map(x=>x.dataset.repeatDate));el.querySelector('[data-all]').onclick=()=>copy(weekDays(visible));}
 function edit(row){if(!leave())return;editing=row?.id;const el=host.querySelector('[data-assignment]');el.innerHTML=`<label>Subcontratista<select data-company>${[...new Set([...SUBCONTRATOS.map(s=>s.nombre),...teams.map(t=>t.contractor),row?.contractor,value('contratista')].filter(Boolean))].map(c=>`<option ${c===(row?.contractor||value('contratista'))?'selected':''}>${esc(c)}</option>`).join('')}</select></label><label>Equipo<input data-team list="lpTeams" value="${esc(row?.teamName||'')}"></label><datalist id="lpTeams">${[...new Map([...teams,...rows].map(t=>[t.teamId,t])).values()].map(t=>`<option value="${esc(t.teamName)}">${esc(t.contractor)}</option>`).join('')}</datalist><label>Personas previstas<input data-people type="number" min="1" step="1" value="${row?.people||''}"></label><label>Jornada<select data-fraction>${[[1,'Completa'],[.5,'Media'],[.25,'Un cuarto']].map(([v,label])=>`<option value="${v}" ${v===(row?.fraction||1)?'selected':''}>${label}</option>`).join('')}</select></label><details><summary>Horas y rendimiento específico (opcional)</summary><label>Horas por persona<input type="number" min="0" max="24" step="any" data-hours-assigned value="${row?.hours||''}"></label><label>Horas de una jornada de referencia<input type="number" min="0" max="24" step="any" data-reference-hours value="${row?.referenceHours||''}"></label><label>Rendimiento específico de este equipo (misma unidad y base)<input type="number" min="0" step="any" data-row-rate value="${row?.productivity?.rate||''}"></label><label>Cuadrillas completas (solo base técnica de cuadrilla)<input type="number" min="0" step="1" data-row-crews value="${row?.crews||''}"></label><label class="check"><input type="checkbox" data-crew-confirmed ${row?.crewConfirmed?'checked':''}>Confirmo la composición técnica de estas cuadrillas</label></details><p role="alert"></p><button type="button" data-apply-assignment>Aplicar equipo</button><button type="button" data-cancel-assignment>Cancelar</button>`;
 el.querySelector('[data-cancel-assignment]').onclick=()=>{editing=null;el.replaceChildren();};el.querySelector('[data-apply-assignment]').onclick=()=>{try{const get=k=>el.querySelector('[data-'+k+']').value;const next={date:selected,contractor:get('company'),teamName:get('team').trim(),people:Number(get('people')),fraction:Number(get('fraction')),hours:get('hours-assigned')?Number(get('hours-assigned')):null,referenceHours:get('reference-hours')?Number(get('reference-hours')):null,crews:get('row-crews')?Number(get('row-crews')):null,crewConfirmed:el.querySelector('[data-crew-confirmed]').checked,specialty:value('especialidad'),responsible:value('responsable'),...(get('row-rate')?{productivity:{rate:Number(get('row-rate')),unit:reference().unit,basis:reference().basis,crew:reference().crew,status:'provisional',source:'Estimación provisional del supervisor',actor:sessionActor()?.id,at:new Date().toISOString()}}:{})};if(next.hours!=null&&(!(next.hours>0)||next.hours>24||!(next.referenceHours>0)||next.referenceHours>24))throw Error('Indica horas válidas y la duración de referencia.');const id=selected+'|'+teamKey(next.contractor,next.teamName);if(rows.some(r=>r.id===id&&r.id!==editing)&&!confirm('Este equipo ya está programado. ¿Actualizar su asignación?'))return;rows=putAssignment(rows.filter(r=>r.id!==editing),next);editing=null;refresh();changed();}catch(e){el.querySelector('[role=alert]').textContent=e.message;}};}
 function summarize(){const relevant=rows.filter(r=>r.date>=value('inicioPlan')&&r.date<=value('finPlan')),cap=scheduleCapacity(relevant,reference(),value('unidad')),quantity=Number(value('cantidad')),required=reference().rate>0&&reference().unit===value('unidad')?quantity/reference().rate:null;
 const ref=reference(),resourceLabel={'persona-dia':'jornadas-persona','persona-hora':'horas-persona','cuadrilla-dia':'jornadas-cuadrilla','cuadrilla-hora':'horas-cuadrilla'}[ref.basis],scheduled={'persona-dia':cap.personDays,'persona-hora':cap.personHours,'cuadrilla-dia':cap.crewDays,'cuadrilla-hora':cap.crewHours}[ref.basis],production=cap.calculated?`Producción estimada${cap.unknown?' parcial':''}: ${cap.production.toLocaleString('es-CL')} ${value('unidad')}. Diferencia frente al compromiso: ${(cap.production-quantity).toLocaleString('es-CL')} ${value('unidad')}.`:'Rendimiento pendiente de calibración o personal sin programar.';
 const uniform=relevant.every(r=>!r.productivity),text=`${cap.personDays.toLocaleString('es-CL')} jornadas-persona programadas. ${production} Compromiso: ${quantity} ${value('unidad')}.${cap.unknown?' '+cap.unknown+' asignaciones pendientes de calibración.':''}${required!=null&&uniform&&(!ref.basis.startsWith('cuadrilla')||cap.calculated>0)?' Bajo este rendimiento se necesitan '+required.toLocaleString('es-CL')+' '+resourceLabel+'; faltan '+Math.max(0,required-scheduled).toLocaleString('es-CL')+'.':''}`;
 host.querySelector('[data-daily-capacity]').textContent=text+(rows.length===0&&Number(value('dotacion'))>0?' Dotación anterior conservada: '+value('dotacion')+' personas, todavía sin distribución diaria.':'');
 const conflicts=relevant.filter(r=>references.some(other=>other.id===r.id)),outside=rows.length!==relevant.length;
 host.querySelector('[data-calculation]').textContent=`${ref.source}. Base: ${ref.basis}; unidad: ${ref.unit}. Se suma la capacidad de cada equipo según sus jornadas u horas y su rendimiento. La proporcionalidad es una estimación provisional; no representa asistencia ni producción real.${outside?' Hay asignaciones fuera del período: ajusta las fechas o elimínalas antes de guardar.':''}${conflicts.length?' Posible coincidencia de equipo y fecha con otra actividad: verifica los horarios.':''}`;
 const trim=host.querySelector('[data-trim]');trim.hidden=!outside;trim.onclick=()=>{if(leave()&&confirm('¿Quitar únicamente las asignaciones fuera del nuevo período?')){rows=relevant;refresh();changed();}};
 const criteria={partida:form.querySelector('[data-part-name]').value.trim(),unit:value('unidad'),contractor:value('contratista'),conditions:form.querySelector('[data-rate-notes]').value,teams:[...new Set(relevant.map(r=>r.teamName))]},history=comparableHistory(activities,attendance,criteria);
 const useHistory=host.querySelector('[data-use-history]');useHistory.hidden=history.length<3;useHistory.onclick=()=>{historical={status:'observado',source:'Historial verificado de '+history.length+' actividades comparables',activityIds:history.map(r=>r.activityId),sampleSize:history.length,criteria,range:[Math.min(...history.map(r=>r.rate)),Math.max(...history.map(r=>r.rate))]};form.elements.rendimientoPlan.value=history.reduce((n,r)=>n+r.quantity,0)/history.reduce((n,r)=>n+r.hours,0);form.querySelector('[data-rate-basis]').value='persona-hora';form.querySelector('[data-rate-unit]').value=value('unidad');rateAt=new Date().toISOString();changed();};
 host.querySelector('[data-history]').textContent=history.length?`Antecedentes verificados comparables: ${history.length} actividades; ${(history.reduce((n,r)=>n+r.quantity,0)/history.reduce((n,r)=>n+r.hours,0)).toLocaleString('es-CL')} ${value('unidad')}/persona-hora observado. No sustituye un rendimiento aprobado; revisar condiciones y equipos.`:'Sin antecedentes verificados comparables. La estimación manual es provisional.';

 const review=form.querySelectorAll('.lpWizardReview')[2];if(review){let box=review.querySelector('[data-schedule-review]');if(!box){box=document.createElement('div');box.dataset.scheduleReview='';review.append(box);}box.textContent=text;const list=document.createElement('details');list.innerHTML='<summary>Ver personal por día y equipo</summary>'+relevant.slice().sort((a,b)=>a.date.localeCompare(b.date)).map(r=>'<p>'+esc(r.date+' · '+r.contractor+' · '+r.teamName+': '+r.people+' personas · '+(r.hours!=null?r.hours+' h/persona':r.fraction+' jornada'))+'</p>').join('');box.append(list);}
 }
 form.addEventListener('input',e=>{if(e.target.matches?.('[name=rendimientoPlan],[name=unidad],[name=contratista],[data-rate-basis],[data-rate-unit],[data-rate-notes],[data-part-name]'))historical=null;if(e.target.name==='rendimientoPlan'||e.target.matches('[data-rate-basis],[data-rate-unit],[data-rate-notes]'))rateAt=new Date().toISOString();if(['inicioPlan','finPlan'].includes(e.target.name)&&!host.querySelector('[data-apply-assignment]'))refresh();else summarize();});form.addEventListener('change',summarize);form.addEventListener('click',()=>queueMicrotask(summarize));refresh();
 return {read:()=>({schedule:structuredClone(rows),estimateReference:reference()}),pending:()=>!!host.querySelector('[data-apply-assignment]')};
}
